def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the large rectangular 1-background object.
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)

    out = [[1] * (c1 - c0 + 1) for _ in range(r1 - r0 + 1)]
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if grid[r][c] not in (0,):
                out[r - r0][c - c0] = grid[r][c]

    # Isolated markers outside the rectangle specify marker colors and corner positions.
    outside = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != 0 and not (r0 <= r <= r1 and c0 <= c <= c1)]
    if len(outside) >= 3:
        mr = (min(r for r, c, v in outside), max(r for r, c, v in outside))
        mc = (min(c for r, c, v in outside), max(c for r, c, v in outside))
        H, W = len(out), len(out[0])

        # Remove the markers originally embedded in the rectangle.
        marker_colors = {v for _, _, v in outside}
        for i in range(H):
            for j in range(W):
                if out[i][j] in marker_colors:
                    out[i][j] = 1

        for r, c, color in outside:
            i = 1 if r <= (mr[0] + mr[1]) / 2 else H - 2
            j = 1 if c <= (mc[0] + mc[1]) / 2 else W - 2
            out[i][j] = color

    return out
